def spec():
    return {"grades": GRADES, "codes": CODES, "channels": {k: {"label": v[0], "what": v[1], "unit": v[2], "fields": [dict(key=f[0], label=f[1], unit=f[2]) for f in FIELDS[k]]}
                                                      for k, v in CHANNEL_META.items()},
            "procedures": {k: {"element": v["element"], "label": v["label"], "codes": v["codes"], "note": v["note"], "channels": v["channels"],
                               "params": [dict(key=p[0], label=p[1], unit=p[2], default=p[3], min=p[4], max=p[5]) for p in v["params"]]}
                           for k, v in PROCEDURES.items()},
            "exposure": EXPOSURE_LIMIT,
            "disclaimer": "Limits are the team's reading of the IS codes and are flagged 'verify'. Check against the current BIS text. Not for certification."}


# ---------------------------------------------------------------------------------------------- helpers
def sigma_assumed(fck):  # IS 456 Table 8 (assumed standard deviation when no history exists) - verify
    return 3.5 if fck <= 15 else 4.0 if fck <= 25 else 5.0 if fck <= 50 else 6.0


def ec_code(fck):  # IS 456 cl.6.2.3.1  Ec = 5000*sqrt(fck) MPa
    return 5000.0 * math.sqrt(fck)


def f1_bending(E_mpa, d_m, L_m, rho=2400.0):
    """Fundamental bending frequency of a simply supported prism: f = (pi d / 2L^2) * sqrt(E / 12 rho)."""
    return math.pi * d_m / (2 * L_m ** 2) * math.sqrt(E_mpa * 1e6 / (12 * rho))


def interp(x, pts):
    xs, ys = zip(*pts)
    return float(np.interp(x, xs, ys))


def _status(ok, warn=False):
    return "PASS" if ok else ("REVIEW" if warn else "FAIL")


def chk(name, value, limit, rule, status, clause, unit="", note=None):
    return {"name": name, "value": None if value is None else round(float(value), 3), "limit": limit, "rule": rule, "status": status,
            "clause": clause, "unit": unit, "note": note}


# ---------------------------------------------------------------------------------------------- simulation (SIMULATED data)
def simulate(proc, fck, params, defect, rng, channels):
    """Return (metrics, series, image_width_mm). defect 0 = sound, 1 = badly defective. All SIMULATED."""
    d = float(defect)
    sg = sigma_assumed(fck)
    el = PROCEDURES[proc]["element"]
    m, ser = {}, {}
    f_c = (fck + 1.65 * sg * 0.55) * (1 - 0.45 * d) * (1 + rng.normal(0, 0.035))  # true compressive strength, N/mm2
    Ec = ec_code(fck) * (1 - 0.4 * d) * (1 + rng.normal(0, 0.04))  # MPa
    upv = max(2.0, 4.65 * (1 - 0.30 * d) + rng.normal(0, 0.05))
    width = 0.0
    n = 48
    if proc == "cube_compression":
        s = params["size_mm"]
        A = s * s
        P = f_c * A / 1000.0
        T = f_c / 14.0 * 60.0  # s at 14 N/mm2/min
        t = np.linspace(0, T, n)
        ser["load"] = [t.tolist(), (P * (t / T) ** 1.04).tolist()]
        eps_peak = f_c / Ec * 1e6 * 1.25
        stress = np.linspace(0, f_c, n)
        ser["strain"] = [stress.tolist(), (stress / Ec * 1e6 * (1 + 0.6 * (stress / f_c) ** 3)).tolist()]
        m["load"] = {"peak_kN": P}
        e_meas = 0.33 * f_c / (0.33 * f_c / Ec * 1e6) * 1e-3 * 1e6 / 1e6  # = Ec/1000 GPa
        m["strain"] = {"peak_ue": eps_peak, "e_gpa": Ec / 1000.0 * (1 + rng.normal(0, 0.02))}
        m["deflection"] = {"max_defl_mm": eps_peak * 1e-6 * s * 1.8}
        ser["deflection"] = [stress.tolist(), (stress / f_c * m["deflection"]["max_defl_mm"]).tolist()]
        f_kHz = upv * 1000.0 / (2 * s / 1000.0) / 1000.0  # longitudinal resonance of the cube path
        m["vibration"] = {"freq_before": f_kHz * 1000 / (1 - 0.30 * 0) , "freq_after": f_kHz * 1000}
        m["vibration"]["freq_before"] = 4.65 * 1000 / (2 * s / 1000.0)
        m["upv"] = {"velocity_kms": upv}
        m["temperature"] = {"temp_c": 27.0 + rng.normal(0, 0.8)}
        m["moisture"] = {"moisture_pct": 6.5 + 3.0 * d + rng.normal(0, 0.3)}
        width = 0.15 + 2.6 * d
    elif proc == "beam_flexure":
        b, dd, l = params["b_mm"], params["d_mm"], params["span_mm"]
        fcr = 0.7 * math.sqrt(fck) * 1.12 * (1 - 0.5 * d) * (1 + rng.normal(0, 0.06))
        P = fcr * b * dd ** 2 / l / 1000.0  # kN (total, two-point)
        I = b * dd ** 3 / 12.0
        defl = 23 * P * 1000 * l ** 3 / (648 * Ec * I)
        t = np.linspace(0, 1, n)
        ser["load"] = [(t * 100).tolist(), (P * t).tolist()]
        ser["deflection"] = [(P * t).tolist(), (defl * t * (1 + 0.15 * t ** 3)).tolist()]
        eps = fcr / Ec * 1e6
        ser["strain"] = [(P * t).tolist(), (eps * t).tolist()]
        m["load"] = {"peak_kN": P}
        m["deflection"] = {"max_defl_mm": defl * 1.15, "residual_mm": defl * 0.05 * (1 + 4 * d)}
        m["strain"] = {"peak_ue": eps, "e_gpa": Ec / 1000.0}
        f0 = f1_bending(Ec, dd / 1000, l / 1000)
        m["vibration"] = {"freq_before": f0 * (1 + rng.normal(0, 0.01)), "freq_after": f0 * (0.55 - 0.1 * d) * (1 + rng.normal(0, 0.01))}
        m["upv"] = {"velocity_kms": upv}
        m["temperature"] = {"temp_c": 27.5 + rng.normal(0, 1.0)}
        m["moisture"] = {"moisture_pct": 6.0 + 3.0 * d + rng.normal(0, 0.3)}
        width = 0.05 + 1.2 * (0.4 + 0.6 * d)
    elif proc in ("beam_load_test", "slab_load_test"):
        L, D, bw = params["span_m"], params["depth_mm"], params["width_mm"]
        dmax = (L * 1000 / 800.0) * (1 + 2.2 * d) * (1 + rng.normal(0, 0.05))
        resid = dmax * (0.08 + 0.55 * d) * (1 + rng.normal(0, 0.05))
        hrs = np.arange(0, 49, 1.0)
        defl = np.where(hrs <= 24, dmax * (0.85 + 0.15 * (1 - np.exp(-hrs / 6.0))), resid + (dmax - resid) * np.exp(-(hrs - 24) / 5.0))
        ser["deflection"] = [hrs.tolist(), defl.tolist()]
        Pt = (1.25 * 12.0 * L * bw / 1000.0)  # kN: illustrative 1.25 x 12 kN/m2-equivalent over the strip (informational only)
        ser["load"] = [hrs.tolist(), np.where(hrs <= 24, Pt, 0.0).tolist()]
        eps = 280.0 * (1 + 1.4 * d) * (1 + rng.normal(0, 0.05))
        ser["strain"] = [hrs.tolist(), np.where(hrs <= 24, eps * (0.9 + 0.1 * (1 - np.exp(-hrs / 6.0))), eps * 0.1 * (1 + 3 * d) + (eps * 0.9) * np.exp(-(hrs - 24) / 5.0)).tolist()]
        m["load"] = {"peak_kN": Pt}
        m["deflection"] = {"max_defl_mm": dmax, "residual_mm": resid}
        m["strain"] = {"peak_ue": eps, "e_gpa": Ec / 1000.0}
        f0 = f1_bending(Ec, D / 1000, L) * 0.6  # 0.6: mass/support flexibility factor (indicative)
        m["vibration"] = {"freq_before": f0 * (1 + rng.normal(0, 0.015)), "freq_after": f0 * (0.995 - 0.25 * d) * (1 + rng.normal(0, 0.015))}
        m["upv"] = {"velocity_kms": upv}
        m["temperature"] = {"temp_c": 29.0 + rng.normal(0, 1.5)}
        m["moisture"] = {"moisture_pct": 6.0 + 3.0 * d + rng.normal(0, 0.3)}
        width = 0.04 + 0.5 * d * (0.8 + 0.4 * rng.random())
    else:  # column_axial
        b, D, Lc, k, fy, ast = params["b_mm"], params["D_mm"], params["length_mm"], params["k"], params["fy"], params["ast_pct"]
        Ag = b * D
        Asc = Ag * ast / 100.0
        Ac = Ag - Asc
        Pu = (0.4 * fck * Ac + 0.67 * fy * Asc) / 1000.0
        Pt = Pu * 1.38 * (1 - 0.55 * d) * (1 + rng.normal(0, 0.04))
        t = np.linspace(0, 1, n)
        sig = Pt * 1000 / (Ac + 7 * Asc)
        eps_u = sig / Ec * 1e6
        ser["load"] = [(t * 100).tolist(), (Pt * t).tolist()]
        sh = eps_u * 1e-6 * Lc
        ser["deflection"] = [(Pt * t).tolist(), (sh * t * (1 + 0.8 * t ** 3)).tolist()]
        ser["strain"] = [(Pt * t).tolist(), (eps_u * t * (1 + 0.8 * t ** 3)).tolist()]
        emin = max(Lc * k / 500.0 + D / 30.0, 20.0)
        m["load"] = {"peak_kN": Pt}
        m["deflection"] = {"max_defl_mm": sh * 1.8, "lateral_mm": emin * (0.35 + 1.9 * d) * (1 + rng.normal(0, 0.08))}
        m["strain"] = {"peak_ue": eps_u * 1.8, "e_gpa": Ec / 1000.0}
        f0 = f1_bending(Ec, min(b, D) / 1000, Lc / 1000 * k)
        m["vibration"] = {"freq_before": f0 * (1 + rng.normal(0, 0.01)), "freq_after": f0 * (0.995 - 0.25 * d) * (1 + rng.normal(0, 0.01))}
        m["upv"] = {"velocity_kms": upv}
        m["temperature"] = {"temp_c": 28.0 + rng.normal(0, 1.2)}
        m["moisture"] = {"moisture_pct": 6.0 + 3.0 * d + rng.normal(0, 0.3)}
        width = 0.05 + 1.0 * d
    m["rf"] = {"freq_khz": 1000.0 * (1 - 0.08 * d + rng.normal(0, 0.0005)), "f0_khz": 1000.0}
    m["crack"] = {"max_width_mm": width}
    keep = set(channels)
    return {k: v for k, v in m.items() if k in keep}, {k: v for k, v in ser.items() if k in keep}, width


# ---------------------------------------------------------------------------------------------- evaluation
def _score_from(checks, indicative=None):
    """Channel score 0-100: the worst check decides; INFO-only channels use an indicative score."""
    sc = [c["_score"] for c in checks if c.get("_score") is not None]
    if sc:
        return round(min(sc), 1)
    return None if indicative is None else round(indicative, 1)


def evaluate(proc, grade, params, metrics, extra=None):
    """Turn raw per-channel metrics into checks, statuses and scores. Pure function (no database)."""
    fck = GRADES[grade]
    P = PROCEDURES[proc]
    out = {}
    exposure_w = EXPOSURE_LIMIT.get((extra or {}).get("exposure", "normal"), 0.3)
    Ec = ec_code(fck)

    def done(key, checks, indicative=None, info=None):
        sc = _score_from(checks, indicative)
        sts = [c["status"] for c in checks if c["status"] in ("PASS", "REVIEW", "FAIL")]
        status = "FAIL" if "FAIL" in sts else "REVIEW" if "REVIEW" in sts else "PASS" if sts else "INFO"
        out[key] = {"key": key, "label": CHANNEL_META[key][0], "unit": CHANNEL_META[key][2], "active": True, "status": status, "score": sc,
                    "metrics": metrics[key], "checks": [{k: v for k, v in c.items() if k != "_score"} for c in checks], "info": info}

    for key in P["channels"]:
        if key not in metrics:
            out[key] = {"key": key, "label": CHANNEL_META[key][0], "unit": CHANNEL_META[key][2], "active": False, "status": "INACTIVE", "score": None,
                        "metrics": None, "checks": [], "info": "No sensor / no reading for this channel."}
            continue
        m = metrics[key]
        checks = []
        if key == "load":
            P_kN = m["peak_kN"]
            if proc == "cube_compression":
                s = params["size_mm"]
                fc = P_kN * 1000.0 / (s * s)
                m["strength_mpa"] = round(fc, 2)
                st = _status(fc >= fck, fc >= fck - 4)
                c = chk("Cube compressive strength", fc, f"≥ fck = {fck:.0f} N/mm²", "single-result check against grade", st, "IS 516; IS 456 cl.16", "N/mm²",
                        "A single cube is not an acceptance test: see group compliance for 4 results.")
                c["_score"] = interp(fc / fck, [(0.6, 0), (0.85, 40), (1.0, 72), (1.2, 100)])
                checks.append(c)
            elif proc == "beam_flexure":
                b, dd, l = params["b_mm"], params["d_mm"], params["span_mm"]
                fcr = P_kN * 1000.0 * l / (b * dd * dd)
                m["fcr_mpa"] = round(fcr, 2)
                lim = 0.7 * math.sqrt(fck)
                c = chk("Flexural strength fcr", fcr, f"≥ 0.7√fck = {lim:.2f} N/mm²", "IS 456 design estimate", _status(fcr >= lim, fcr >= 0.85 * lim), "IS 516; IS 456 cl.6.2.2", "N/mm²",
                        "IS 456 gives 0.7√fck as an estimate, not an acceptance limit. REVIEW means 'lower than expected'.")
                c["_score"] = interp(fcr / lim, [(0.5, 0), (0.85, 45), (1.0, 75), (1.25, 100)])
                checks.append(c)
            elif proc == "column_axial":
                b, D, Lc, kf, fy, ast = (params[x] for x in ("b_mm", "D_mm", "length_mm", "k", "fy", "ast_pct"))
                Ag = b * D
                Asc = Ag * ast / 100.0
                Pu = (0.4 * fck * (Ag - Asc) + 0.67 * fy * Asc) / 1000.0
                m["design_capacity_kN"] = round(Pu, 1)
                c = chk("Tested peak load vs design capacity", P_kN, f"≥ Pu = {Pu:.0f} kN (0.4·fck·Ac + 0.67·fy·Asc)", "short axially loaded column", _status(P_kN >= Pu, P_kN >= 0.9 * Pu),
                        "IS 456 cl.39.3", "kN", "Design capacity already includes partial safety factors; a sound column should test above it.")
                c["_score"] = interp(P_kN / Pu, [(0.6, 0), (0.9, 40), (1.0, 72), (1.3, 100)])
                checks.append(c)
                ratio = Lc * kf / D
                checks.append(chk("Slenderness le/D", ratio, "< 12 for a short column", "design classification", "PASS" if ratio < 12 else "REVIEW", "IS 456 cl.25.1.2", "",
                                  "Above 12 the column is slender and additional moments apply."))
            else:  # load tests
                checks.append(chk("Test load held 24 h", P_kN, "information", "load level used", "INFO", "IS 456 cl.17.6", "kN",
                                  "Under IS 456 the superimposed load is a multiple of the design loads: confirm the figure with the structural engineer."))
        elif key == "deflection":
            dm = m.get("max_defl_mm")
            if proc in ("beam_load_test", "slab_load_test"):
                L, D = params["span_m"], params["depth_mm"]
                lim_nr = 40.0 * L * L / D
                lim_svc = L * 1000 / 250.0
                res = m.get("residual_mm")
                c1 = chk("Max deflection vs 40·l²/D", dm, f"< {lim_nr:.2f} mm → recovery test not needed", "IS 456 load test", "PASS" if dm < lim_nr else "INFO", "IS 456 cl.17.6.2", "mm",
                         "Above this value the recovery check below decides." if dm >= lim_nr else None)
                c1["_score"] = 100 if dm < lim_nr else None
                checks.append(c1)
                c2 = chk("Deflection vs span/250", dm, f"≤ {lim_svc:.1f} mm", "serviceability", _status(dm <= lim_svc, dm <= 1.2 * lim_svc), "IS 456 cl.23.2(a)", "mm")
                c2["_score"] = interp(dm / lim_svc, [(0.3, 100), (1.0, 62), (1.6, 10)])
                checks.append(c2)
                if res is not None and dm > 0 and dm >= lim_nr:
                    rec = (1 - res / dm) * 100
                    m["recovery_pct"] = round(rec, 1)
                    c3 = chk("Recovery 24 h after unloading", rec, "≥ 75 %", "IS 456 load test", _status(rec >= 75, rec >= 70), "IS 456 cl.17.6.3", "%",
                             "If below 75 % the test may be repeated after 72 h (second recovery must reach about 80 %).")
                    c3["_score"] = interp(rec, [(40, 0), (65, 35), (75, 70), (90, 100)])
                    checks.append(c3)
            elif proc == "beam_flexure":
                I = params["b_mm"] * params["d_mm"] ** 3 / 12.0
                checks.append(chk("Mid-span deflection at failure", dm, "information (no code limit for prisms)", "IS 516", "INFO", "IS 516", "mm"))
            elif proc == "column_axial":
                emin = max(params["length_mm"] * params["k"] / 500.0 + params["D_mm"] / 30.0, 20.0)
                m["e_min_mm"] = round(emin, 1)
                checks.append(chk("Axial shortening at peak", dm, "information", "deformation", "INFO", "-", "mm"))
                lat = m.get("lateral_mm")
                if lat is not None:
                    c = chk("Lateral deflection vs minimum eccentricity", lat, f"≤ e_min = {emin:.1f} mm (l/500 + D/30, ≥ 20 mm)", "indicative", _status(lat <= emin, lat <= 1.5 * emin), "IS 456 cl.25.4", "mm",
                            "e_min is a design minimum, so this comparison is only an indicator of unexpected bending.")
                    c["_score"] = interp(lat / emin, [(0.4, 100), (1.0, 65), (2.0, 10)])
                    checks.append(c)
            else:
                checks.append(chk("Axial deformation at failure", dm, "information", "deformation", "INFO", "IS 516", "mm"))
        elif key == "strain":
            pe = m["peak_ue"]
            eg = m.get("e_gpa")
            if eg:
                ratio = eg * 1000.0 / Ec
                c = chk("Measured Ec vs IS 456 (5000√fck)", eg, f"≈ {Ec/1000:.1f} GPa (≥ 0.85×)", "IS 456 cl.6.2.3.1", _status(ratio >= 0.85, ratio >= 0.75), "IS 456 cl.6.2.3.1", "GPa",
                        "IS 456 notes that Ec can vary widely with aggregates, so treat as indicative.")
                c["_score"] = interp(ratio, [(0.5, 0), (0.75, 40), (0.9, 80), (1.05, 100)])
                checks.append(c)
            checks.append(chk("Peak strain", pe, "information", "strain gauge", "INFO", "-", "µε"))
        elif key == "vibration":
            fb, fa = m.get("freq_before"), m.get("freq_after")
            if fb and fa:
                drop = (fb - fa) / fb * 100.0
                m["freq_drop_pct"] = round(drop, 1)
                if proc == "cube_compression":
                    checks.append(chk("Resonant frequency (pulse path)", fa, "information", "comparative only", "INFO", "-", "Hz"))
                elif proc == "beam_flexure":
                    checks.append(chk("Frequency change after test to failure", drop, "information", "a cracked prism is expected to lose stiffness", "INFO", "-", "%",
                                      "Use the pre-test frequency of other prisms as a quality reference instead."))
                else:
                    c = chk("Natural frequency change", drop, "< 3 % drop (warn) / 6 % (alert)", "StructuraSense project threshold", "PASS" if drop < 3 else "REVIEW" if drop < 6 else "FAIL", "project rule (no IS limit)", "%",
                            "A falling frequency means lost stiffness. After a flexure TEST TO FAILURE a large drop is expected.")
                    c["_score"] = interp(drop, [(0, 100), (3, 80), (6, 40), (15, 5)])
                    checks.append(c)
            elif fa or fb:
                checks.append(chk("Natural frequency", fa or fb, "information", "single reading", "INFO", "-", "Hz"))
        elif key == "temperature":
            t = m["temp_c"]
            if proc == "cube_compression":
                c = chk("Curing/test temperature", t, "27 ± 2 °C", "IS 516 curing", _status(25 <= t <= 29, 23 <= t <= 31), "IS 516 (curing)", "°C")
                c["_score"] = interp(abs(t - 27), [(2, 100), (4, 60), (8, 10)])
                checks.append(c)
            else:
                c = chk("Specimen temperature", t, "5–40 °C working range (indicative)", "thermal stress exposure", _status(5 <= t <= 40, 0 <= t <= 45), "project rule (no IS limit)", "°C",
                        "Large daily swings cause restrained thermal stress; watch the range over time.")
                c["_score"] = interp(t, [(-5, 0), (5, 70), (20, 100), (40, 80), (50, 30), (60, 5)])
                checks.append(c)
        elif key == "moisture":
            mo = m["moisture_pct"]
            c = chk("Moisture reading", mo, "≤ 10 % (indicative)", "water infiltration", "PASS" if mo <= 10 else "REVIEW" if mo <= 14 else "FAIL", "project rule (no IS limit)", "%",
                    "Cubes just out of a curing tank read wet; compare like with like.")
            c["_score"] = interp(mo, [(4, 100), (8, 75), (12, 35), (16, 5)])
            checks.append(c)
        elif key == "rf":
            f, f0 = m["freq_khz"], m.get("f0_khz") or m["freq_khz"]
            delta = (f - f0) / f0 * 100.0
            m["delta_pct"] = round(delta, 2)
            c = chk("RF-coil resonance shift", delta, "|shift| < 2 % (indicative)", "EXPERIMENTAL - no Indian Standard", "PASS" if abs(delta) < 2 else "REVIEW" if abs(delta) < 5 else "FAIL", "none (experimental)", "%",
                    "Indicates a possible internal discontinuity; confirm with UPV / GPR before acting.")
            c["_score"] = interp(abs(delta), [(0.3, 100), (1.0, 85), (2.5, 55), (5.0, 15), (8.0, 0)])
            checks.append(c)
        elif key == "upv":
            v = m["velocity_kms"]
            q = "Excellent" if v > 4.5 else "Good" if v > 3.5 else "Medium" if v > 3.0 else "Doubtful"
            m["quality"] = q
            c = chk("Pulse velocity quality", v, "> 3.5 km/s = Good or better", f"IS 13311 (1) grading: {q}", "PASS" if v > 3.5 else "REVIEW" if v > 3.0 else "FAIL", "IS 13311 (Part 1)", "km/s",
                    "Grading is indicative; steel, moisture and path length affect velocity.")
            c["_score"] = interp(v, [(2.5, 0), (3.0, 30), (3.5, 65), (4.5, 95), (5.0, 100)])
            checks.append(c)
        elif key == "crack":
            w = m["max_width_mm"]
            if proc == "cube_compression":
                checks.append(chk("Failure crack width (post-test photo)", w, "information", "failure pattern", "INFO", "IS 516", "mm"))
            elif proc == "beam_flexure":
                checks.append(chk("Crack width at failure", w, "information", "prism fails by cracking", "INFO", "IS 516", "mm"))
            else:
                c = chk("Crack width under load", w, f"≤ {exposure_w} mm ({(extra or {}).get('exposure', 'normal')} exposure)", "IS 456 crack control", _status(w <= exposure_w, w <= 1.3 * exposure_w), "IS 456 cl.35.3.2", "mm",
                        "0.3 mm general, 0.2 mm weather/moisture exposed, 0.1 mm severe (verify against current text).")
                c["_score"] = interp(w / exposure_w, [(0.2, 100), (1.0, 62), (2.0, 5)])
                checks.append(c)
        indic = None
        if not any(c.get("_score") is not None for c in checks):
            indic = {"load": 75, "deflection": 80, "strain": 85, "vibration": 85, "crack": 80}.get(key, 80)
        done(key, checks, indic, "Indicative score (no code limit)" if indic else None)
    return out


def summarize(chs):
    act = [c for c in chs.values() if c["active"]]
    sc = [c["score"] for c in act if c["score"] is not None]
    index = round(sum(sc) / len(sc), 1) if sc else None
    sts = [c["status"] for c in act]
    if not act:
        return "INCOMPLETE", None
    verdict = "FAIL" if "FAIL" in sts else "REVIEW" if "REVIEW" in sts else "PASS"
    return verdict, index


def cube_group(grade, tests):
    """IS 456 cl.16 / Table 11 style compliance over groups of 4 cube results (most recent first). verify=True."""
    fck = GRADES[grade]
    sg = sigma_assumed(fck)
    res = [t for t in tests if t["element_type"] == "cube" and t["grade"] == grade]
    vals = []
    for t in res:
        v = (json.loads(t["metrics_json"]).get("load") or {}).get("strength_mpa")
        if v is not None:
            vals.append((t["id"], float(v)))
    if len(vals) < 4:
        return {"grade": grade, "n": len(vals), "complete": False, "message": f"Needs 4 cube results for {grade}; {len(vals)} available."}
    last4 = vals[:4]
    mean = sum(v for _, v in last4) / 4.0
    add = 3.0 if fck <= 15 else 4.0
    need_mean = max(fck + 0.825 * sg, fck + add)
    need_ind = fck - add
    ok_m = mean >= need_mean
    ok_i = all(v >= need_ind for _, v in last4)
    return {"grade": grade, "n": 4, "complete": True, "ids": [i for i, _ in last4], "values": [round(v, 2) for _, v in last4], "mean": round(mean, 2),
            "mean_required": round(need_mean, 2), "individual_required": round(need_ind, 2), "sigma_assumed": sg,
            "mean_ok": ok_m, "individual_ok": ok_i, "verdict": "PASS" if ok_m and ok_i else "FAIL",
            "rule": f"IS 456 Table 11 (as read by the team): mean of 4 ≥ max(fck + 0.825σ, fck + {add:.0f}), each ≥ fck − {add:.0f}", "verify": True}


