def _crack_image(rng, width_mm, test_id):
    """Make a synthetic concrete photo with a crack of the requested width, then MEASURE it with the real detector."""
    import cv2

    from . import synth_images, vision
    scale = synth_images.SCALE_PX_PER_MM
    if width_mm < 0.1:
        bgr, _ = synth_images.make_image(rng, width_px=None)
    else:
        bgr, _ = synth_images.make_image(rng, width_px=max(1.0, width_mm * scale), branches=1 if width_mm < 0.5 else 2)
    res, work, mask = vision.analyze(bgr, scale)
    o, ov = f"lab_{test_id}_orig.jpg", f"lab_{test_id}_overlay.png"
    cv2.imwrite(str(config.UPLOAD_DIR / o), work, [cv2.IMWRITE_JPEG_QUALITY, 88])
    cv2.imwrite(str(config.UPLOAD_DIR / ov), vision.overlay(work, mask, res["segments_detail"]))
    return res, o, ov


def run_test(user, element_type, procedure, grade, params, mode, defect=0.0, metrics=None, channels=None, label=None, notes=None,
             exposure="normal", seed=None):
    if procedure not in PROCEDURES or PROCEDURES[procedure]["element"] != element_type:
        raise ValueError("Unknown test procedure for this element type.")
    if grade not in GRADES:
        raise ValueError("Pick a concrete grade such as M25.")
    P = PROCEDURES[procedure]
    prm = {}
    for key, lab, unit, dflt, lo, hi in P["params"]:
        try:
            v = float(params.get(key, dflt))
        except (TypeError, ValueError):
            raise ValueError(f"{lab} must be a number.")
        if not (lo <= v <= hi) or not math.isfinite(v):
            raise ValueError(f"{lab} must be between {lo} and {hi} {unit}.".replace("  ", " "))
        prm[key] = v
    chans = [c for c in (channels or P["channels"]) if c in P["channels"]]
    tid = db.uid()
    rng = np.random.default_rng(seed if seed is not None else int.from_bytes(tid.encode()[:4], "little"))
    fck = GRADES[grade]
    series, img = {}, (None, None)
    if mode == "sim":
        defect = max(0.0, min(1.0, float(defect)))
        m, series, width = simulate(procedure, fck, prm, defect, rng, chans)
        if "crack" in chans:
            res, o, ov = _crack_image(rng, width, tid)
            m["crack"] = {"max_width_mm": float(res["max_width_mm"] or 0.0), "detected": bool(res["crack_detected"]), "length_mm": res["length_mm"], "severity": res["severity"],
                          "nominal_input_mm": round(width, 3)}
            img = (o, ov)
    elif mode == "manual":
        defect = None
        m = {}
        for ch in chans:
            row = (metrics or {}).get(ch) or {}
            clean = {}
            for k, v in row.items():
                if v in (None, ""):
                    continue
                try:
                    fv = float(v)
                except (TypeError, ValueError):
                    raise ValueError(f"{CHANNEL_META[ch][0]}: '{k}' must be a number.")
                if not math.isfinite(fv):
                    raise ValueError(f"{CHANNEL_META[ch][0]}: '{k}' must be a finite number.")
                clean[k] = fv
            req = {"load": "peak_kN", "deflection": "max_defl_mm", "strain": "peak_ue", "temperature": "temp_c", "moisture": "moisture_pct",
                   "rf": "freq_khz", "upv": "velocity_kms", "crack": "max_width_mm"}
            if ch == "vibration":
                if "freq_before" in clean or "freq_after" in clean:
                    m[ch] = clean
            elif req[ch] in clean:
                m[ch] = clean
        if not m:
            raise ValueError("Enter at least one sensor reading.")
    else:
        raise ValueError("Mode must be 'sim' or 'manual'.")
    chs = evaluate(procedure, grade, prm, m, {"exposure": exposure})
    for k, s in series.items():
        if chs.get(k, {}).get("active"):
            chs[k]["series"] = {"x": [round(float(v), 4) for v in s[0]], "y": [round(float(v), 4) for v in s[1]],
                                "x_label": {"cube_compression": {"load": "time (s)", "strain": "stress (N/mm²)", "deflection": "stress (N/mm²)"}}.get(procedure, {}).get(k)
                                or ("time (h)" if procedure in ("beam_load_test", "slab_load_test") else "load (kN)" if k in ("deflection", "strain") else "% of test"),
                                "y_label": chs[k]["unit"]}
    verdict, index = summarize(chs)
    row = {"id": tid, "ts_ms": db.now_ms(), "element_type": element_type, "procedure": procedure, "label": (label or "")[:80] or None, "grade": grade,
           "fck": fck, "params_json": json.dumps({**prm, "exposure": exposure}), "source": mode, "defect": defect,
           "metrics_json": json.dumps(m), "channels_json": json.dumps(chs), "verdict": verdict, "index_score": index,
           "image_file": img[0], "overlay_file": img[1], "notes": (notes or "")[:400] or None, "user_name": (user or {}).get("name")}
    db.insert("element_tests", row)
    return out_row(row, full=True)


def out_row(r, full=False):
    o = {k: r[k] for k in ("id", "ts_ms", "element_type", "procedure", "label", "grade", "fck", "source", "defect", "verdict", "index_score", "notes", "user_name")}
    o["procedure_label"] = PROCEDURES[r["procedure"]]["label"]
    o["params"] = json.loads(r["params_json"])
    chs = json.loads(r["channels_json"])
    o["channel_status"] = {k: {"status": v["status"], "score": v["score"], "active": v["active"]} for k, v in chs.items()}
    if full:
        o["channels"] = chs
        o["image_url"] = f"/api/files/uploads/{r['image_file']}" if r.get("image_file") else None
        o["overlay_url"] = f"/api/files/uploads/{r['overlay_file']}" if r.get("overlay_file") else None
        o["note"] = PROCEDURES[r["procedure"]]["note"]
        o["codes"] = PROCEDURES[r["procedure"]]["codes"]
    return o


def csv_rows(rows):
    import csv
    import io
    buf = io.StringIO()
    w = csv.writer(buf)
    w.writerow(["id", "time_iso", "element", "procedure", "label", "grade", "source(SIM=simulated, manual)", "verdict", "index_score"] + [f"{k}_status" for k in CHANNEL_META] + [f"{k}_score" for k in CHANNEL_META])
    import datetime
    for r in rows:
        o = out_row(r)
        cs = o["channel_status"]
        w.writerow([o["id"], datetime.datetime.fromtimestamp(o["ts_ms"] / 1000, datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ"), o["element_type"], o["procedure"], o["label"] or "", o["grade"],
                    "SIMULATED" if o["source"] == "sim" else "MANUAL ENTRY", o["verdict"], o["index_score"]]
                   + [cs.get(k, {}).get("status", "") for k in CHANNEL_META] + [cs.get(k, {}).get("score", "") for k in CHANNEL_META])
    return buf.getvalue()
